recipes.code:
{
  "inputs": [
    {
      "id": "dokploy-api-key",
      "type": "promptString",
      "description": "Optional when local Dokploy credentials already exist. Otherwise provide the Dokploy API key.",
      "password": true
    },
    {
      "id": "dokploy-profiles-json",
      "type": "promptString",
      "description": "Optional JSON object of named Dokploy targets. Use this when you want explicit named profiles in addition to the local default target.",
      "password": true
    }
  ],
  "servers": {
    "dokploy": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@vibetools/dokploy-mcp@4.0.0"
      ],
      "env": {
        "DOKPLOY_URL": "<dokploy-url>",
        "DOKPLOY_API_KEY": "${input:dokploy-api-key}",
        "DOKPLOY_PROFILES_JSON": "${input:dokploy-profiles-json}"
      }
    }
  }
}
